const stories=[{slug:'anya-nikita',count:12,tag:'ФОТОРЕАЛИСТИЧНАЯ ИСТОРИЯ',title:'Аня & Никита',text:'Случайное знакомство в Twinby, первое свидание в кино, поездки и свой маленький мир. История о любви, которая живёт и в больших событиях, и в повседневных мелочах.',tags:['Переписки','Коллажи','Личные шутки'],note:'Реалистичные сцены, рукописные подписи и тёплое оформление личного дневника. Представлены 12 изображений из готовой работы.'},{slug:'alena-leonid',count:14,tag:'РИСОВАННЫЙ КОМИКС',title:'Алёна & Леонид',text:'Знакомство через друзей, волнение перед встречей, забавные недопонимания и первый поцелуй. История, где даже поездка на такси превращается в отдельное приключение.',tags:['Живые диалоги','Юмор','Первое свидание'],note:'Рисованные сцены, выразительные контуры и диалоги в облачках. Представлены обложка и 13 страниц готового комикса.'}];
let activeStory=0,activePage=0;
const dialog=document.getElementById('art-dialog');
function imagePath(index){return `assets/${stories[activeStory].slug}/${String(index).padStart(2,'0')}.jpg`}
function renderPage(){const story=stories[activeStory],caption=activePage===0?'Обложка':`Страница ${activePage}`;for(const id of ['case-image','reader-image']){const img=document.getElementById(id);img.src=imagePath(activePage);img.alt=`${story.title} — ${caption.toLowerCase()}`}document.getElementById('page-counter').textContent=`${caption} · ${activePage+1} / ${story.count}`;document.getElementById('reader-counter').textContent=`${activePage+1} / ${story.count}`;document.getElementById('reader-title').textContent=story.title;for(const id of ['page-prev','reader-prev'])document.getElementById(id).disabled=activePage===0;for(const id of ['page-next','reader-next'])document.getElementById(id).disabled=activePage===story.count-1;document.querySelectorAll('[data-page]').forEach(b=>{const selected=Number(b.dataset.page)===activePage;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected))});document.querySelector('.reader-page').scrollTo(0,0)}
function selectStory(index){activeStory=index;activePage=0;const story=stories[index];document.querySelectorAll('[data-story]').forEach(b=>{const selected=Number(b.dataset.story)===index;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected))});for(const field of ['tag','title','text','note'])document.getElementById('case-'+field).textContent=story[field];document.getElementById('case-tags').replaceChildren(...story.tags.map(t=>{const span=document.createElement('span');span.textContent=t;return span}));document.getElementById('page-thumbnails').replaceChildren(...Array.from({length:story.count},(_,i)=>{const b=document.createElement('button');b.type='button';b.dataset.page=i;b.setAttribute('aria-label',i===0?'Обложка':`Страница ${i}`);const img=document.createElement('img');img.src=imagePath(i);img.alt='';img.loading='lazy';b.append(img);b.addEventListener('click',()=>{activePage=i;renderPage()});return b}));renderPage()}
function movePage(delta){activePage=Math.max(0,Math.min(stories[activeStory].count-1,activePage+delta));renderPage()}
document.querySelectorAll('[data-story]').forEach(b=>b.addEventListener('click',()=>selectStory(Number(b.dataset.story))));document.querySelectorAll('[data-case-link]').forEach(b=>b.addEventListener('click',()=>selectStory(Number(b.dataset.caseLink))));
for(const id of ['page-prev','reader-prev'])document.getElementById(id).addEventListener('click',()=>movePage(-1));for(const id of ['page-next','reader-next'])document.getElementById(id).addEventListener('click',()=>movePage(1));
document.getElementById('case-open').addEventListener('click',()=>{dialog.showModal();document.body.style.overflow='hidden'});document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.style.overflow='';dialog.classList.remove('zoomed');document.getElementById('reader-zoom').setAttribute('aria-pressed','false');document.getElementById('reader-zoom').textContent='Увеличить'});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();movePage(1)}if(e.key==='ArrowLeft'){e.preventDefault();movePage(-1)}});document.getElementById('reader-zoom').addEventListener('click',e=>{const zoom=dialog.classList.toggle('zoomed');e.currentTarget.setAttribute('aria-pressed',String(zoom));e.currentTarget.textContent=zoom?'Уместить':'Увеличить'});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
selectStory(0);
document.getElementById('brief-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const name=String(data.get('name')).trim(),story=String(data.get('story')).trim();if(!name||!story){document.getElementById(!name?'name':'story').focus();return}document.getElementById('brief-output').value=`Здравствуйте! Хочу персональный комикс.\n\nМеня зовут: ${name}\nПовод: ${data.get('occasion')}\nМоя идея: ${story}\n\nОриентир бюджета: около 3 000 ₽. Хочу уточнить объём, печать и сроки.`;document.getElementById('brief-result').hidden=false;document.getElementById('copy-status').textContent='Заявка не отправлена. Скопируйте текст для сообщения.';document.getElementById('brief-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})});
document.getElementById('copy-brief').addEventListener('click',async()=>{const output=document.getElementById('brief-output');try{await navigator.clipboard.writeText(output.value);document.getElementById('copy-status').textContent='Текст скопирован. Его можно вставить в сообщение.'}catch{output.focus();output.select();document.getElementById('copy-status').textContent='Выделили текст. Скопируйте его вручную.'}});
